//barrier
function setBarrier(x,y,z,block){
  world[''].setBlock(x,y-1,z,block)
  world[''].setBlock(x,y+2,z,block)
  world[''].setBlock(x+1,y,z,block)
  world[''].setBlock(x,y,z+1,block)
  world[''].setBlock(x-1,y,z,block)
  world[''].setBlock(x,y,z-1,block)
}
function countPlayers(){
  let i = 0
  for(var p of world.players){
    if(!p.spectator) i++
  }
  return i
}
world.on('tick',function(){
  if(world.waitingRestart) return
  if(world.waiting){
    if(countPlayers() >= 4){
      world.waiting = false
      for(var p of world.players){
        if(!world.beds[p.bed]) continue
        let pos = world.beds[p.bed]
        setBarrier(pos[0],pos[1]+10,pos[2], 0)
      }
      world.sendAll({type:'title',data:'Starting',fadeIn:500,fadeOut:1000,stay:2000})
    }else return
  }
  var bedCount = 0
  for(var p of world.players){
    if(!world.beds[p.bed]) continue
    var bed = world.beds[p.bed]
    if(bed[3]) bedCount++; else continue
    if(!world[''].getBlock(bed[0],bed[1],bed[2])){
      bed[3] = false
      world.sendAll({
        type:'message',
        data:p.username+'\'s bed got destroyed',
        fromServer:true
      })
      p.connection.send({
        type:'title',
        data:'You lost :(',
        color:'red',
        fadeIn:500,fadeOut:1000,stay:2000
      })
    }
  }
  if(bedCount <= 1){
    var bed
    for(var i = 0; i<world.beds.length; i++){
      if(world.beds[i][3]) bed = i
    }
    var winner
    for(var i of world.players){
      if(i.bed === bed){
        i.send({
          type:'title',
          data:'You won!',
          color:'green'
        })
        winner = i
      }
    }
    if(winner){
      world.sendAll({
        type:'message',
        data:winner.username+' won!',
        fromServer:true
      })
    }
    setTimeout(() => {
      for(let p of world.players){
        p.connection.send({type:'title',data:'Join again to play again!',fadeIn:500,fadeOut:1000,stay:2000})
        p.setGameMode('spectator')
        p.bed = undefined
      }
    }, 5000)
    world.waitingRestart = true
  }
})

function onjoin(e){
  let player = e.player
  if(world.waiting && countPlayers() < 4){
    var availableBeds = [true,true,true,true]
    for(var p of world.players){
      availableBeds[p.bed] = false
    }
    player.bed = availableBeds.indexOf(true)
    let pos = world.beds[player.bed]
    player.tp(pos[0],pos[1]+10,pos[2])
    setBarrier(pos[0],pos[1]+10,pos[2],blockIds.barrier)
    p.setGameMode('survival')
  }else{
    p.setGameMode('spectator')
  }
  player.setDefaults()
  player.inventory.hotbar.fill(null)
  player.inventory.main.fill(null)
  player.connection.send({
    type:'message',
    data:'Wait for other players',
    fromServer:true
  })
}
world.on('join', onjoin)
world.on('respawn', e => {
  if(world.beds[e.player.bed]){
    let pos = world.beds[e.player.bed]
    e.player.tp(pos[0],pos[1]+10,pos[2])
  }else p.setGameMode('spectator')
})
restartGame()

