    { pos: [12, 31, -12], subtype: 1 },
    { pos: [-12, 31, 12], subtype: 1 },
    { pos: [12, 31, 12], subtype: 1 },
    { pos: [-12, 31, -12], subtype: 1 },
    { pos: [0, 37, -17], subtype: 2 },
    { pos: [-17, 37, 0], subtype: 2 },
    { pos: [0, 37, 17], subtype: 2 },
    { pos: [17, 37, 0], subtype: 2 },
    { pos: [-17, 48, 0], subtype: 1 },
    { pos: [17, 48, 0], subtype: 1 },
    { pos: [12, 58, -12], subtype: 2 },
    { pos: [-12, 58, 12], subtype: 2 },
    { pos: [12, 58, 12], subtype: 2 },
    { pos: [-12, 58, -12], subtype: 2 },
  ];

  if (initRoom) {
    world.waiting = true;
    //0-2: spawn, 3-5: wall center, 6: is depth
    world.placements = [[0, 23, 21, 0, 23, 19, false], [0, 23, -21, 0, 23, -19, false], [-21, 23, 0, -19, 23, 0, true], [21, 23, 0, 19, 23, 0, true]];
    interval = setInterval(function() {
      if (countPlayers() == 1 && !world.waiting && playerAmount > 1) {
        player.connection.send({
          type: "title",
          data: "VICTORY",
          sub: "You won!",
          color: "yellow"
        });
        setTimeout(() => {
          clearInterval(spawnloop);
          clearInterval(interval);
          for (var p of getPlayers()) {
            p.setGameMode('spectator')
          }
        }, 5000);
      }
      if (world.waiting) {
        if (countPlayers() >= playerAmount) {
          world.waiting = false;
          loading = true;
          start()
        } else return;
      }
      if (!gameStart) {
        loading = false;
        for (var p of getPlayers()) {
          if (!joined.includes(p.username, 0)) loading = true;
        }
        if (loading == false) {
          if (countPlayers() != playerAmount) return;
          gameStart = true;
          for (let c of chests) {
            world.onchunkload(() => setChestLoot(c.pos, c.subtype), c.pos[0],c.pos[1],c.pos[2],"")
          }
          let maxCount = 5;
          var count = maxCount;
          var countdown = setInterval(function() {
            if (count == 0) {
              world.sendAll({
                type: "title",
                data: `FIGHT!`,
              });
              world.sendAll({
                type: "playSound",
                data: "note.harp",
                pitch: 2
              });
            } else {
              world.sendAll({
                type: "title",
                data: count.toString(),
              });
              world.sendAll({
                type: "playSound",
                data: "note.harp"
              });
            }
            count--;
            if (count < 0) {
              for (var p of getPlayers()) {
                if (world.placements[p.placement][6]) {
                  clearWallD(world.placements[p.placement], 0);
                } else {
                  clearWallW(world.placements[p.placement], 0);
                }
                // this doesn't work now
                /*world.on('hit', function(e) {
                  let force = 2;
                  if (e.data.holding == 236) {
                    e.data.velx *= force
                    e.data.velz *= force
                  }
                })*/
              }
              clearInterval(countdown)
              spawnloop = setInterval(() => {
                world[""].addItems(0, 47, -21, 0, 0, 0, 402, true, 1)
                world[""].addItems(0, 47, 21, 0, 0, 0, 402, true, 1)
                world[""].addItems(world.placements[p.placement][0], world.placements[p.placement][1], world.placements[p.placement][2], 0, 0, 0, 401, true, 1)
              }, 10000);
            }
          }, 1000);
        }
      }
    }, 1000);
  }
});
